import { LAppDelegate } from './lappdelegate';

declare global {
  interface Window {
    LingshanLive2D?: {
      setSpeaking: (speaking: boolean, text?: string) => void;
      setListening: (listening: boolean) => void;
      setModel: (modelName: string) => void;
    };
  }
}

function setupLingshanBridge(): void {
  const getManager = () =>
    LAppDelegate.getInstance().getMainSubdelegate()?.getLive2DManager();

  window.LingshanLive2D = {
    setSpeaking: (speaking: boolean, text = ''): void => {
      getManager()?.setExternalLipSync(speaking, text);
      document.body.classList.toggle('speaking', speaking);
    },
    setListening: (listening: boolean): void => {
      document.body.classList.toggle('listening', listening);
      if (!listening) {
        getManager()?.setExternalLipSync(false, '');
      }
    },
    setModel: (modelName: string): void => {
      getManager()?.changeModelByName(modelName);
    }
  };

  window.addEventListener('message', event => {
    const data = event.data || {};
    if (data.model) {
      window.LingshanLive2D?.setModel(String(data.model));
    }
    if (typeof data.listen !== 'undefined') {
      window.LingshanLive2D?.setListening(Boolean(data.listen));
    }
    if (typeof data.speak !== 'undefined') {
      window.LingshanLive2D?.setSpeaking(Boolean(data.speak), data.text || '');
    }
  });

  const modelName = new URLSearchParams(location.search).get('model');
  if (modelName) {
    window.LingshanLive2D.setModel(modelName);
  }
}

/**
 * ブラウザロード後の処理
 */
window.addEventListener(
  'load',
  (): void => {
    // Initialize WebGL and create the application instance
    if (!LAppDelegate.getInstance().initialize()) {
      return;
    }

    setupLingshanBridge();
    LAppDelegate.getInstance().run();
  },
  { passive: true }
);

/**
 * 終了時の処理
 */
window.addEventListener(
  'beforeunload',
  (): void => LAppDelegate.releaseInstance(),
  { passive: true }
);
